#!/usr/bin/env python3
import copy,json,sys,tempfile,unittest
from pathlib import Path
HERE=Path(__file__).resolve().parent;sys.path.insert(0,str(HERE));from protocol import compare,validate_event
H="a"*64;IDENTITY={"source_commit":"c","source_tree":"t","source_archive_sha256":H,"pygame_sysfont_sha256":H,"font_manifest_sha256":H,"episode_path":"/episode","episode_sha256":H,"font_registry_path":"/registry","font_registry_sha256":H,"python_executable":"/python","pygame_sysfont_path":"/sysfont"};UI={"currentAgent":None,"curSelectedInventoryIdx":0,"showScoreToUser":False,"lastActionMessage":"","messageQueueText":[],"dialogToDisplay":None,"inModal":False,"inDiscoveryFeedModal":False,"curSelectedArgument1Idx":0,"curSelectedArgument2Idx":0,"curSelectedArgument1Obj":None,"curSelectedArgument2Obj":None,"argObjectsList":[],"lastDiscoveryFeedPostCount":0,"extendedPlayEnabled":False};API={"thread_id":918273,"world_is_none":False,"num_user_agents":0,"ui_count":0,"steps":0,"acted_count":0,"task_progress_count":0};WORLD={"size":[32,32],"grid_dimensions":[32,32],"grid_sha256":H,"agents":0,"task_count":0,"step":0,"world_history":0,"teleport_locations":0,"live_user_playing":False,"random_seed":None,"rng_is_none":True,"uuid_existing":0,"sprite_count":1,"sprite_dimensions_sha256":H,"object_property_count":1,"object_properties_sha256":H,"material_property_count":1,"material_properties_sha256":H,"object_errors":[],"object_warnings":[],"feed":{"articles":[],"updatePosts":[],"uniquePostIDs":1},"feed_sha256":H,"start_time_is_finite":True};REQUESTS=[["Arial",8,False,False],["monospace",10,False,False],["monospace",15,False,False],["monospace",15,True,False]]
def event(mode):return {"schema_version":"argo-world-initialization-cell/v1","mode":mode,**IDENTITY,"projection":{"window_size":[1536,1324],"api":copy.deepcopy(API),"world":copy.deepcopy(WORLD),"ui":copy.deepcopy(UI),"font_calls":[{"request":copy.deepcopy(x),"constructor_path":"/font","font_sha256":H} for x in REQUESTS]},"font_discovery_subprocesses":[["/usr/X11/bin/fc-list",":","file","family","style"]] if mode=="native" else [],"os_fork_denied":None if mode=="native" else True,"forbidden_calls":[],"scenario_loads":0,"tasks_created":0,"agents_created":0,"ticks":0,"agent_observations":0,"model_calls":0,"spend_usd":0.0}
class Tests(unittest.TestCase):
 def check(self,value,mode="native",suffix=b"\n"):
  with tempfile.TemporaryDirectory(dir=HERE) as td:
   p=Path(td)/"e";p.write_bytes(json.dumps(value,separators=(",",":"),sort_keys=True).encode()+suffix);return validate_event(p,mode,IDENTITY)
 def test_valid_native_and_pinned(self):self.assertTrue(self.check(event("native"))["passed"],self.check(event("native")));self.assertTrue(self.check(event("pinned"),"pinned")["passed"])
 def test_extra_or_truncated_event_fails(self):v=event("native");v["extra"]=1;self.assertFalse(self.check(v)["passed"]);self.assertFalse(self.check(event("native"),suffix=b"")["passed"])
 def test_forbidden_activity_fails(self):v=event("native");v["ticks"]=1;self.assertFalse(self.check(v)["passed"]);v=event("native");v["forbidden_calls"]=["tick"];self.assertFalse(self.check(v)["passed"])
 def test_initial_state_mutation_fails(self):v=event("native");v["projection"]["world"]["agents"]=1;self.assertFalse(self.check(v)["passed"]);v=event("native");v["projection"]["api"]["world_is_none"]=True;self.assertFalse(self.check(v)["passed"])
 def test_font_or_process_mutation_fails(self):v=event("pinned");v["projection"]["font_calls"][0]["request"][1]=9;self.assertFalse(self.check(v,"pinned")["passed"]);v=event("pinned");v["font_discovery_subprocesses"]=[["x"]];self.assertFalse(self.check(v,"pinned")["passed"])
 def test_compare_full_projection(self):n=event("native");p=event("pinned");self.assertTrue(compare(n,p)["passed"]);p["projection"]["world"]["grid_sha256"]="b"*64;self.assertFalse(compare(n,p)["passed"])
